const SAME_CONTROL = {
  'mouse-input-device': 'input-device',
  'mouse-ads-multiplier': 'controller-ads-multiplier',
  'mouse-focus-multiplier': 'controller-ads-focus',
  'mouse-ads-behavior': 'controller-ads-behavior',
  'mouse-ads-transition': 'controller-ads-transition',
  'mouse-simplified-controls': 'simplified-controls',
  'mouse-low-motor-strain': 'low-motor-strain',
  'mouse-custom-zoom': 'controller-zoom-custom',
  'mouse-third-person-correction': 'controller-third-person-correction',
  'mouse-sprint-assist': 'controller-sprint-assist',
  'mouse-sprint-assist-delay': 'controller-sprint-assist-delay',
  'mouse-mantle-assist': 'controller-mantle-assist',
  'mouse-corner-slice': 'controller-corner-slice',
  'mouse-sprint': 'controller-sprint-behavior',
  'mouse-airborne-mantle': 'controller-airborne-mantle',
  'mouse-sprint-restore': 'controller-sprint-restore',
  'mouse-slide-sprint': 'controller-slide-sprint',
  'mouse-melee': 'controller-melee',
  'mouse-mount': 'controller-weapon-mount',
  'mouse-throw': 'controller-alternate-throw',
  'mouse-equipment': 'controller-equipment',
  'mouse-inventory': 'controller-inventory',
  'mouse-interact-reload': 'controller-interact-reload',
  'mouse-armor': 'controller-armor',
};

export function settingExplanation(entry, language) {
  const key = entry.id.replace(/^mw4-/, '');
  const definitionKey = Object.hasOwn(SAME_CONTROL, key) ? SAME_CONTROL[key] : key;
  const definition = Object.hasOwn(EXPLANATIONS, definitionKey) ? EXPLANATIONS[definitionKey] : undefined;
  const english = language === 'en';
  if (definition) return definition[english ? 1 : 0];

  if (/^(mouse|controller)-zoom-/.test(key)) {
    return english
      ? 'Adjusts how fast your aim moves at this magnification. Below 1.00 it moves more slowly. This applies with custom sensitivity per zoom enabled.'
      : 'Legt fest, wie schnell du bei dieser Vergrößerung zielst. Unter 1.00 reagiert der Blick langsamer. Der Wert greift bei eigener Empfindlichkeit pro Zoomstufe.';
  }
  if (key.startsWith('controller-bind-')) {
    return english
      ? 'Selects the in-game action for the ' + entry.en + ' button. Available actions depend on the layout you chose.'
      : 'Legt die Spielaktion für „' + entry.de + '“ fest. Welche Aktionen zur Wahl stehen, hängt von der Tastenbelegung ab.';
  }
  const streak = key.match(/^key-streak-(\d)$/)?.[1];
  if (streak) {
    return english
      ? 'Uses the matching streak in slot ' + streak + ' after you earn it in the match.'
      : 'Löst die Abschussserie in Platz ' + streak + ' aus, nachdem du sie im Match verdient hast.';
  }
  return '';
}
